interface Pembayaran {
  nama: string;
  bayar(jumlah: number): string;
}
class Tunai implements Pembayaran {
  nama = "Tunai";
  bayar(jumlah: number): string {
    return `terima ${jumlah}`;
  }
}
class Kartu implements Pembayaran {
  nama = "Kartu";
  constructor(private bank: string, private biaya: number) {}
  bayar(jumlah: number): string {
    return `tagih ${jumlah + this.biaya} ke ${this.bank}`;
  }
}
const semua: Pembayaran[] = [new Tunai(), new Kartu("BNI", 2500)];
for (const c of semua) console.log(c.nama + ": " + c.bayar(40000));

