interface Menu {
  nama: string;
  harga(): number;
}
class Teh implements Menu {
  nama = "Teh";
}
console.log(new Teh().nama);

interface Penyapa {
  sapa(n: string): string;
}
class Biasa implements Penyapa {
  sapa(n: string) {
    return "Halo " + n;
  }
}
class Keras implements Penyapa {
  sapa(n: string) {
    return ("Halo " + n).toUpperCase();
  }
}
const d: Penyapa[] = [new Biasa(), new Keras()];
for (const p of d) console.log(p.sapa("Rina"));

