interface Kurir {
  nama: string;
  ongkir(beratKg: number): number;
}
class Reguler implements Kurir {
  nama = "Reguler";
  ongkir(beratKg: number): number {
    return beratKg * 5000;
  }
}
class Kilat implements Kurir {
  nama = "Kilat";
  ongkir(beratKg: number): number {
    return Math.max(15000, beratKg * 9000);
  }
}
function termurah(daftar: Kurir[], berat: number): string {
  let pilih = daftar[0];
  for (const k of daftar) {
    if (k.ongkir(berat) < pilih.ongkir(berat)) pilih = k;
  }
  return pilih.nama;
}
const semua: Kurir[] = [new Kilat(), new Reguler()];
console.log(termurah(semua, 1));
console.log(termurah(semua, 3));
